const charName = encodeURIComponent(query.trim());
const response = await fetch(`https://api.tibiadata.com/v4/character/${charName}`);
const data = await response.json();

if (!data.character || !data.character.character || !data.character.character.name) {
  return `Personagem "${query}" não encontrado ou não existe no Tibia.`;
}

const c = data.character.character;
const deaths = (data.character.deaths || []).slice(0, 3).map(d => `${d.time}: morto no level ${d.level} por ${d.reason}`);

return JSON.stringify({
  nome: c.name,
  level: c.level,
  vocacao: c.vocation,
  mundo: c.world,
  status: c.status,
  guilda: c.guild ? `${c.guild.rank} da ${c.guild.name}` : 'Nenhuma',
  residencia: c.residence,
  ultimo_login: c.last_login,
  mortes_recentes: deaths.length > 0 ? deaths : 'Nenhuma morte recente registrada'
});

const worldName = encodeURIComponent(query.trim());
const response = await fetch(`https://api.tibiadata.com/v4/world/${worldName}`);
const data = await response.json();

if (!data.world || !data.world.name) {
  return `Mundo/servidor "${query}" não encontrado.`;
}

const w = data.world;
return JSON.stringify({
  mundo: w.name,
  status: w.status,
  jogadores_online: w.players_online,
  tipo_pvp: w.pvp_type,
  localizacao: w.location,
  tipo_servidor: w.server_type
});
